// Compose the assignment email from the task row + looked-up assignee/client.
const rec = ($('Trigger').first().json.body || {}).record || {};
const assignee = (Array.isArray($('Lookup assignee').first().json) ? $('Lookup assignee').first().json[0] : $('Lookup assignee').first().json) || {};
const client = (Array.isArray($json) ? $json[0] : $json) || {};

const email = assignee.email || '';
const name = assignee.full_name || 'there';
const clientName = client.name || '';
const title = rec.title || 'a task';
const priority = (rec.priority || '').toUpperCase();
const due = rec.due_date || '';
const appUrl = 'https://workspace.nixgensolutions.com/tasks';

// Task title, names and client come from DB rows that members edit: escape them
// for the HTML body only (subject and sheet columns stay raw text).
const esc = (s) => String(s ?? '').replace(/[&<>"']/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c]));

const MNL = 'Asia/Manila';
const ts = rec.created_at || new Date().toISOString();
const d = new Date(ts);
const date = new Intl.DateTimeFormat('en-CA', { timeZone: MNL, year: 'numeric', month: '2-digit', day: '2-digit' }).format(d);
const time = new Intl.DateTimeFormat('en-GB', { timeZone: MNL, hour: '2-digit', minute: '2-digit', second: '2-digit' }).format(d);

const meta = [clientName && ('Client: ' + esc(clientName)), priority && ('Priority: ' + esc(priority)), due && ('Due: ' + esc(due))].filter(Boolean).join(' &nbsp;·&nbsp; ');
const html = `<div style="font-family:system-ui,-apple-system,Segoe UI,Roboto,sans-serif;color:#111">
  <h2 style="margin:0 0 4px">New task assigned to you</h2>
  <p style="margin:0 0 16px;color:#666">Hi ${esc(name)}, you've been assigned a task in DeskDev Studio.</p>
  <div style="padding:14px 16px;border:1px solid #eee;border-radius:10px">
    <div style="font-size:16px;font-weight:600">${esc(title)}</div>
    ${meta ? `<div style=\"margin-top:6px;color:#666;font-size:13px\">${meta}</div>` : ''}
  </div>
  <p style="margin-top:18px"><a href="${appUrl}" style="background:#2563eb;color:#fff;text-decoration:none;padding:9px 14px;border-radius:8px;font-size:14px">Open the board</a></p>
  <p style="margin-top:20px;color:#999;font-size:12px">Sent by n8n</p></div>`;

// Skip cleanly if the assignee has no email on file.
if (!email) return [];
return [{ json: {
  to: email,
  subject: 'New task assigned: ' + title,
  html,
  // Row for the Assignments/Emails sheet tab:
  Timestamp: ts, Date: date, Time: time,
  Task: title, TaskId: rec.id || '',
  Assignee: name, Email: email, Client: clientName,
  Status: 'sent',
} }];

// Gmail's send step outputs the Gmail API response ({id, threadId, labelIds}), not
// its input, so the sheet row is rebuilt from Build email: exactly the tab's columns.
return $('Build email').all().map((i) => ({ json: {
  Timestamp: i.json.Timestamp, Date: i.json.Date, Time: i.json.Time,
  Task: i.json.Task, TaskId: i.json.TaskId,
  Assignee: i.json.Assignee, Email: i.json.Email, Client: i.json.Client,
  Status: 'sent',
} }));
